import numpy as np
import matplotlib.pyplot as plt

depth=np.arange(1,81)
gains=[.65,1.0,1.35]
products={g:g**depth for g in gains}
for g,p in products.items():
    print(f'local Jacobian norm {g:.2f}: norm after 80 layers = {p[-1]:.3e}')
rng=np.random.default_rng(0)
# Repeated scalar tanh recurrence: derivative is w*(1-h^2).
traces={}
for w in [.8,1.4,2.0]:
    h=.05; cumulative=1.; vals=[]
    for _ in depth:
        h=np.tanh(w*h); cumulative*=abs(w*(1-h*h)); vals.append(cumulative)
    traces[w]=vals
fig,ax=plt.subplots(1,2,figsize=(10,3.5))
for g,p in products.items(): ax[0].semilogy(depth,p,label=f'q={g}')
for w,p in traces.items(): ax[1].semilogy(depth,p,label=f'tanh w={w}')
ax[0].set_title('idealized Jacobian product'); ax[1].set_title('tanh recurrence')
for a in ax: a.set(xlabel='depth / time steps',ylabel='gradient magnitude'); a.legend(); a.grid(alpha=.3)
plt.tight_layout(); plt.show()
